import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/var/lib/app/data.db')
SECRET_KEY = os.environ.get('SECRET_KEY', 'changeme')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
        db.execute('PRAGMA journal_mode=WAL')
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def verify_session(token):
    """Verify HMAC session token, returns user_id or None"""
    if not token or ':' not in token:
        return None
    parts = token.split(':')
    if len(parts) != 2:
        return None
    user_id, sig = parts
    expected = hmac.new(SECRET_KEY.encode(), user_id.encode(), hashlib.sha256).hexdigest()[:16]
    if hmac.compare_digest(sig, expected):
        return int(user_id)
    return None

@app.route('/api/reports')
def get_reports():
    """Search reports with optional filters"""
    user_id = verify_session(request.headers.get('X-Session-Token'))
    if not user_id:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()

    # Base query - users can only see their own reports
    base_query = "SELECT id, title, created_at, status FROM reports WHERE owner_id = ?"
    params = [user_id]

    # Optional status filter
    status = request.args.get('status')
    if status:
        base_query += " AND status = '" + status + "'"

    # Optional date range
    date_from = request.args.get('from')
    if date_from:
        base_query += " AND created_at >= ?"
        params.append(date_from)

    # Sort order
    sort = request.args.get('sort', 'created_at')
    allowed_sorts = ['created_at', 'title', 'status']
    if sort in allowed_sorts:
        base_query += f" ORDER BY {sort}"

    # Pagination
    limit = min(int(request.args.get('limit', 50)), 200)
    offset = int(request.args.get('offset', 0))
    base_query += " LIMIT ? OFFSET ?"
    params.extend([limit, offset])

    try:
        cursor = db.execute(base_query, params)
        reports = [dict(row) for row in cursor.fetchall()]
        return jsonify({'reports': reports, 'count': len(reports)})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'internal error'}), 500

@app.route('/api/reports/<int:report_id>')
def get_report_detail(report_id):
    user_id = verify_session(request.headers.get('X-Session-Token'))
    if not user_id:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    cursor = db.execute(
        "SELECT * FROM reports WHERE id = ? AND owner_id = ?",
        [report_id, user_id]
    )
    report = cursor.fetchone()
    if not report:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(report))

@app.route('/api/reports', methods=['POST'])
def create_report():
    user_id = verify_session(request.headers.get('X-Session-Token'))
    if not user_id:
        return jsonify({'error': 'unauthorized'}), 401

    data = request.get_json()
    if not data or 'title' not in data:
        return jsonify({'error': 'title required'}), 400

    db = get_db()
    db.execute(
        "INSERT INTO reports (title, body, owner_id, status) VALUES (?, ?, ?, 'draft')",
        [data['title'], data.get('body', ''), user_id]
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
